function activePanelSlug() { const m = location.pathname.match(/^\/p\/([a-z0-9-]+)/i); return m ? m[1] : 'main'; }
async function pickGameImage() { return new Promise(resolve => { const input=document.createElement('input'); input.type='file'; input.accept='image/jpeg,image/png,image/webp'; input.onchange=()=>{const f=input.files&&input.files[0];if(!f)return resolve('');if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>5*1024*1024){toast('Choose JPG, PNG or WEBP up to 5 MB');return resolve('');}const r=new FileReader();r.onload=()=>resolve(String(r.result||''));r.onerror=()=>{toast('Could not read image');resolve('')};r.readAsDataURL(f);};input.click(); }); }
async function pickProofImage() { return new Promise(resolve => { const input=document.createElement('input'); input.type='file'; input.accept='image/png,image/jpeg,image/webp'; input.onchange=async()=>{const f=input.files&&input.files[0];if(!f)return resolve('');if(f.size>4*1024*1024||!/^image\/(png|jpeg|webp)$/.test(f.type)){toast('Choose a PNG/JPG/WEBP image under 4 MB');return resolve('');}const r=new FileReader();r.onload=()=>resolve(String(r.result||''));r.onerror=()=>{toast('Could not read image');resolve('')};r.readAsDataURL(f);};input.click(); }); }
function toast(m) { const t = $('#toast'); t.textContent = m; t.hidden = false; clearTimeout(toast.t); toast.t = setTimeout(() => t.hidden = true, 2600); }
async function api(path, body) {
  const headers = { 'X-Panel-Slug': activePanelSlug() };
  if (body !== undefined) headers['Content-Type'] = 'application/json';
  const r = await fetch('/api/' + path, body === undefined ? { credentials: 'same-origin', headers } : { method: 'POST', credentials: 'same-origin', headers, body: JSON.stringify(body) });
  const j = await r.json().catch(() => ({})); if (!r.ok) { const e = new Error(j.error || 'Failed'); e.status = r.status; throw e; } return j;
}
function loginView(msg) {
  $('#root').innerHTML = `<form class="box login" id="lf"><h1 style="margin-top:0">Admin login</h1><label>Email</label><input id="e" type="email" autocomplete="username" required><label>Password</label><div class="pw-wrap"><input id="p" type="password" autocomplete="current-password" required><button type="button" class="eye" id="eye" aria-label="Show password">👁</button></div><p class="msg-err" id="err">${esc(msg || '')}</p><button class="primary-btn" type="submit">Login</button></form>`;
  $('#eye').onclick = () => { const i = $('#p'); i.type = i.type === 'password' ? 'text' : 'password'; };
  $('#lf').onsubmit = async ev => { ev.preventDefault(); try { let j; try { j = await api('login', { email: $('#e').value, password: $('#p').value }); } catch (first) { if (/Authenticator OTP is required/i.test(first.message)) { const otp = prompt('Enter 6-digit authenticator code:'); if (!otp) throw first; j = await api('login', { email: $('#e').value, password: $('#p').value, otp }); } else throw first; } if (j.adminRedirect) { location.replace(j.adminRedirect); return; } if (!['admin', 'headAdmin', 'panelAdmin', 'superAdmin', 'subAdmin', 'supportAdmin'].includes(j.user.role)) { await api('logout', {}); return loginView('Not an admin account.'); } start(); } catch (x) { $('#err').textContent = x.message; const m=String(x.message).match(/\/p\/([a-z0-9-]+)\/admin/); if(m){const link=document.createElement('a');link.href='/p/'+m[1]+'/admin';link.textContent='Open your Panel Admin login';link.style.display='block';$('#err').appendChild(link);} } };
}
async function start() {
  try { ov = await api('admin/overview'); } catch (x) {
    if (x.status === 403) {
      try {
        const j = await api('me');
        if (j.user && j.user.role === 'panelAdmin' && j.user.panelId && j.user.panelId !== activePanelSlug()) {
          location.replace('/p/' + encodeURIComponent(j.user.panelId) + '/admin'); return;
        }
      } catch (_) {}
    }
    return loginView(x.status === 403 ? 'This account cannot access this panel. Use your assigned Panel Admin URL.' : (x.message || 'Please log in.'));
  }
  if (ov.role === 'headAdmin' && activePanelSlug() !== 'main') { location.replace('/admin'); return; }
  draw(true);
}
